  final hasAnsi = line.codeUnits.any((c) => c == 0x1b);
  final visible = hasAnsi
      ? tuiTextWidth(line.replaceAll(AnsiMarkdown.ansiSgrPattern, ''))
      : tuiTextWidth(line);
  if (visible <= width) return [line];

