      parts.add(_WrapPart(line.substring(i, i + len), 0, 1));
      i += len;
      continue;
    }
    if (runStart < 0 || w != runWidth) {
      endRun(i);
      runStart = i;
      runWidth = w;
      runRunes = 1;
    } else {
      runRunes++;
    }
    i += len;
  }
  endRun(n);
  return parts;
}

