      // alternative matched it as a zero-width rune).
      final len = _sgrTokenLength(units, i, n);
      if (len > 0) {
        parts.add(_WrapPart.style(line.substring(i, i + len)));
        i += len;
      } else {
        parts.add(_WrapPart.style('\x1b'));
        i++;
      }
      continue;
    }
