    int rune;
    var len = 1;
    if (_isSurrogatePairAt(units, i, u)) {
      rune = 0x10000 + ((u - 0xd800) << 10) + (units[i + 1] - 0xdc00);
      len = 2;
    } else {
      rune = u;
    }
    final w = tuiRuneCellWidth(rune);
    if (w == 0) {
      endRun(i);
      parts.add(_WrapPart(line.substring(i, i + len), 0, 1));
      i += len;
      continue;
    }
    if (runStart < 0 || w != runWidth) {
      endRun(i);
      runStart = i;
      runWidth = w;
      runRunes = 1;
    } else {
      runRunes++;
    }
    i += len;
  }
  endRun(n);
  return parts;
}

