final class _WrapPart {
  _WrapPart(this.text, this.runeWidth, this.runes)
    : isStyle = false,
      isSpace = false;

  _WrapPart.style(this.text)
    : runeWidth = 0,
      runes = 0,
      isStyle = true,
      isSpace = false;

  _WrapPart.space()
    : text = ' ',
      runeWidth = 1,
      runes = 1,
      isStyle = false,
      isSpace = true;

  final String text;
  final int runeWidth;
  final int runes;
  final bool isStyle;
  final bool isSpace;
