  final n = units.length;
  var i = 0;
  while (i < n) {
    final u = units[i];
    if (u == 0x20) {
      endRun(i);
      parts.add(_WrapPart.space());
      i++;
      continue;
    }
    if (u == 0x1b) {
      endRun(i);
