+/// Emits one accumulated word: hard-cut when it is wider than the row
+/// (or no longer fits after a carried boundary space), else written whole
+/// after a possible single close. A pure-style word (zero visible width,
+/// e.g. a trailing reset after a boundary space) leaves the carried-space
+/// state untouched, so the end-of-line drop guard treats
+/// 'aaaa \x1b[0m' exactly like 'aaaa '.
+void _wrapFlushWord(_WrapState s) {
+  if (s.wordParts.isEmpty) return;
+  final carried = s.carriedBoundarySpace;
+  if (s.wordVisible > 0) s.carriedBoundarySpace = false;
