    final cap = s.col == 0
        ? (w > s.width ? 1 : s.width ~/ w)
        : (s.width - s.col) ~/ w;
    if (cap <= 0) continue; // row was full: _wrapCloseRow above emptied it
    var take = cap < part.runes - from ? cap : part.runes - from;
