  if (s.wordVisible > s.width) {
    // A single word longer than the width: hard-cut it across rows.
    if (s.col > 0) _wrapCloseRow(s);
    _wrapFlushHardCut(s);
  } else {
    _wrapFlushFit(s);
  }
