/// current row once it fits (after at most one close).
void _wrapFlushFit(_WrapState s) {
  if (s.col > 0 && s.col + s.wordVisible > s.width) _wrapCloseRow(s);
  for (final part in s.wordParts) {
    if (part.isStyle) {
      _wrapWriteStyle(s, part.text);
