    // boundary space): hard-cut it across rows, keeping a carried-space
    // row open as the starting row.
    if (s.col > 0 && !carried) _wrapCloseRow(s);
    _wrapFlushHardCut(s);
  } else {
    _wrapFlushFit(s);
  }
  s.wordParts.clear();
  s.wordVisible = 0;
}
